//! Terminal grid for the OHOS port: vt100 parser state rendered into the
//! upstream `TermSpan` model, plus the Slint-key → PTY-bytes mapping.
//!
//! The upstream renderer (`src/terminal/impls/{presentation,render}.rs`) feeds
//! the UI through `crate::ui::TermSpan`, which is generated by the desktop
//! build; this crate owns its own generated struct, so the span builder is a
//! small, self-contained port of the visible-screen part of `build_row`.
//! Scrollback rendering, search highlighting and emoji images are not wired
//! yet (the terminal shows the live screen only). Text selection covers the
//! visible screen, which is the whole buffer here.

use slint::{Color, SharedString, VecModel};

use crate::{TermMatch, TermSpan};

/// Same 16-colour palette as upstream `ANSI16_DARK`.
const ANSI16: [(u8, u8, u8); 16] = [
    (0x00, 0x00, 0x00),
    (0xcd, 0x31, 0x31),
    (0x0d, 0xbc, 0x79),
    (0xe5, 0xe5, 0x10),
    (0x24, 0x72, 0xc8),
    (0xbc, 0x3f, 0xbc),
    (0x11, 0xa8, 0xcd),
    (0xe5, 0xe5, 0xe5),
    (0x66, 0x66, 0x66),
    (0xf1, 0x4c, 0x4c),
    (0x23, 0xd1, 0x8b),
    (0xf5, 0xf5, 0x43),
    (0x3b, 0x8e, 0xea),
    (0xd6, 0x70, 0xd6),
    (0x29, 0xb8, 0xdb),
    (0xff, 0xff, 0xff),
];

/// One run of cells sharing the same style.
#[derive(Clone)]
pub(crate) struct Run {
    pub(crate) text: String,
    pub(crate) fg: Color,
    pub(crate) bg: Option<Color>,
    pub(crate) bold: bool,
    pub(crate) underline: bool,
    pub(crate) cjk: bool,
    pub(crate) row: i32,
    pub(crate) col: i32,
    pub(crate) cells: i32,
}

impl Run {
    fn same_style(&self, fg: Color, bg: Option<Color>, bold: bool, underline: bool, cjk: bool) -> bool {
        self.fg == fg && self.bg == bg && self.bold == bold && self.underline == underline && self.cjk == cjk
    }
}

/// Rebuilds the whole visible screen into `model`.
///
/// `rules` is the compiled Settings › Output highlighting state; rows are
/// highlighted as they are emitted so a rule change only needs a repaint.
pub fn rebuild(
    parser: &vt100::Parser,
    is_dark: bool,
    model: &VecModel<TermSpan>,
    rules: &crate::output_highlight::Rules,
) {
    let screen = parser.screen();
    let (rows, cols) = screen.size();
    let default_fg = if is_dark {
        (0xd4, 0xd4, 0xd4)
    } else {
        (0x2d, 0x2d, 0x2f)
    };
    let highlight = rules.enabled();

    let mut runs: Vec<Run> = Vec::with_capacity(cols as usize * 2);
    for row in 0..rows {
        let row_start = runs.len();
        let mut col: u16 = 0;
        while col < cols {
            let Some(cell) = screen.cell(row, col) else { break };
            if cell.is_wide_continuation() {
                col += 1;
                continue;
            }
            let text = if cell.has_contents() {
                cell.contents().to_string()
            } else {
                " ".to_string()
            };
            let cells: u16 = if cell.is_wide() { 2 } else { 1 };
            let bold = cell.bold();
            let underline = cell.underline();
            let inverse = cell.inverse();
            let (fg, bg) = resolve_colors(cell.fgcolor(), cell.bgcolor(), bold, inverse, is_dark, default_fg);
            let cjk = contains_cjk(&text);

            // Plain blank cells only matter for their position, which is
            // already carried by the next run's `col`; skipping them keeps
            // an idle screen nearly span-free (no 80-wchar text layouts).
            let blank = text == " " && bg.is_none() && !underline && fg == Color::from_rgb_u8(default_fg.0, default_fg.1, default_fg.2);
            if !blank {
                if let Some(last) = runs.last_mut() {
                    if last.row == row as i32
                        && last.col + last.cells == col as i32
                        && last.same_style(fg, bg, bold, underline, cjk)
                    {
                        last.text.push_str(&text);
                        last.cells += i32::from(cells);
                        col += cells;
                        continue;
                    }
                }
                runs.push(Run {
                    text,
                    fg,
                    bg,
                    bold,
                    underline,
                    cjk,
                    row: i32::from(row),
                    col: i32::from(col),
                    cells: i32::from(cells),
                });
            }
            col += cells;
        }
        if highlight {
            let row_runs: Vec<Run> = runs.split_off(row_start);
            runs.extend(crate::output_highlight::highlight(row_runs, rules, default_fg));
        }
    }

    model.set_vec(
        runs.into_iter()
            .map(|run| TermSpan {
                text: SharedString::from(run.text),
                fg: run.fg,
                bg: run.bg.unwrap_or(Color::from_argb_u8(0, 0, 0, 0)),
                bold: run.bold,
                underline: run.underline,
                row: run.row,
                col: run.col,
                cells: run.cells,
                cjk: run.cjk,
                font: SharedString::new(),
                emoji: false,
                emoji_image: slint::Image::default(),
            })
            .collect::<Vec<_>>(),
    );
}

/// `(cursor-row, cursor-col)`, or `(-1, -1)` when the cursor is hidden.
pub fn cursor(parser: &vt100::Parser) -> (i32, i32) {
    let screen = parser.screen();
    if screen.hide_cursor() {
        (-1, -1)
    } else {
        let (row, col) = screen.cursor_position();
        (i32::from(row), i32::from(col))
    }
}

pub fn app_cursor(parser: &vt100::Parser) -> bool {
    parser.screen().application_cursor()
}

fn resolve_colors(
    fg: vt100::Color,
    bg: vt100::Color,
    bold: bool,
    inverse: bool,
    is_dark: bool,
    default_fg: (u8, u8, u8),
) -> (Color, Option<Color>) {
    let mut fg_rgb = match fg {
        vt100::Color::Default => default_fg,
        vt100::Color::Idx(index) => palette_rgb(index, bold),
        vt100::Color::Rgb(r, g, b) => (r, g, b),
    };
    let mut bg_rgb = match bg {
        vt100::Color::Default => None,
        vt100::Color::Idx(index) => Some(palette_rgb(index, false)),
        vt100::Color::Rgb(r, g, b) => Some((r, g, b)),
    };
    if inverse {
        let bg_used = bg_rgb.unwrap_or(if is_dark {
            (0x1c, 0x1c, 0x1e)
        } else {
            (0xfa, 0xfa, 0xfa)
        });
        bg_rgb = Some(fg_rgb);
        fg_rgb = bg_used;
    }
    (
        Color::from_rgb_u8(fg_rgb.0, fg_rgb.1, fg_rgb.2),
        bg_rgb.map(|(r, g, b)| Color::from_rgb_u8(r, g, b)),
    )
}

pub(crate) fn palette_rgb(index: u8, bold: bool) -> (u8, u8, u8) {
    match index {
        0..=15 => {
            let slot = if bold && index < 8 { index + 8 } else { index };
            ANSI16[usize::from(slot)]
        }
        16..=231 => {
            const LEVELS: [u8; 6] = [0x00, 0x5f, 0x87, 0xaf, 0xd7, 0xff];
            let i = index - 16;
            (LEVELS[usize::from(i / 36)], LEVELS[usize::from((i / 6) % 6)], LEVELS[usize::from(i % 6)])
        }
        _ => {
            let grey = 8 + (index - 232) * 10;
            (grey, grey, grey)
        }
    }
}

/// Characters of one screen row with their starting cell index.
fn row_chars(screen: &vt100::Screen, row: u16) -> Vec<(String, u16)> {
    let cols = screen.size().1;
    let mut out = Vec::new();
    let mut col: u16 = 0;
    while col < cols {
        let Some(cell) = screen.cell(row, col) else { break };
        if cell.is_wide_continuation() {
            col += 1;
            continue;
        }
        let text = if cell.has_contents() {
            cell.contents().to_string()
        } else {
            " ".to_string()
        };
        out.push((text, col));
        col += if cell.is_wide() { 2 } else { 1 };
    }
    out
}

/// Inclusive cell span of `row` covered by an anchor/focus pair.
fn row_span(row: u16, lo: (u16, u16), hi: (u16, u16), cols: u16) -> Option<(u16, u16)> {
    let last = cols.saturating_sub(1);
    let (c0, c1) = if row == lo.0 && row == hi.0 {
        (lo.1.min(hi.1), lo.1.max(hi.1))
    } else if row == lo.0 {
        (lo.1, last)
    } else if row == hi.0 {
        (0, hi.1)
    } else {
        (0, last)
    };
    let c0 = c0.min(last);
    let c1 = c1.min(last);
    if c1 < c0 {
        None
    } else {
        Some((c0, c1))
    }
}

/// Highlight rectangles for a drag selection, one per row.
///
/// Mirrors upstream `selection_rects_visible`, restricted to the live screen
/// (the OHOS port has no scrollback, so row/col are already absolute).
pub fn selection_rects(anchor: (u16, u16), focus: (u16, u16), cols: u16) -> Vec<TermMatch> {
    if anchor == focus {
        return Vec::new();
    }
    let (lo, hi) = if anchor <= focus { (anchor, focus) } else { (focus, anchor) };
    let mut rects = Vec::new();
    for row in lo.0..=hi.0 {
        let Some((c0, c1)) = row_span(row, lo, hi, cols) else { continue };
        rects.push(TermMatch {
            row: i32::from(row),
            col: i32::from(c0),
            len: i32::from(c1 - c0 + 1),
        });
    }
    rects
}

/// Text covered by an anchor/focus pair, rows joined with `\n`.
pub fn selected_text(parser: &vt100::Parser, anchor: (u16, u16), focus: (u16, u16)) -> String {
    if anchor == focus {
        return String::new();
    }
    let screen = parser.screen();
    let cols = screen.size().1;
    let (lo, hi) = if anchor <= focus { (anchor, focus) } else { (focus, anchor) };
    let mut lines = Vec::new();
    for row in lo.0..=hi.0 {
        let Some((c0, c1)) = row_span(row, lo, hi, cols) else { continue };
        let mut line = String::new();
        for (text, start) in row_chars(screen, row) {
            if start >= c0 && start <= c1 {
                line.push_str(&text);
            }
        }
        lines.push(line.trim_end().to_string());
    }
    while lines.last().is_some_and(|line| line.is_empty()) {
        lines.pop();
    }
    lines.join("\n")
}

/// Case-insensitive find matches on the visible screen: `(row, col, len)` per
/// hit, `len` in cells. Used by the 查找 bar to highlight results.
pub fn find_matches(parser: &vt100::Parser, query: &str) -> Vec<(u16, u16, u16)> {
    let needle = query.trim().to_lowercase();
    if needle.is_empty() {
        return Vec::new();
    }
    let screen = parser.screen();
    let rows = screen.size().0;
    let mut out = Vec::new();
    for row in 0..rows {
        let cells = row_chars(screen, row);
        let text: String = cells.iter().map(|(text, _)| text.as_str()).collect();
        let haystack = text.to_lowercase();
        // Character index → starting cell of that character (wide chars are
        // 2 cells, so the cell count and the char count differ).
        let mut cols: Vec<u16> = Vec::new();
        for (text, start) in &cells {
            for _ in 0..text.chars().count() {
                cols.push(*start);
            }
        }
        let mut from = 0usize;
        while from < haystack.len() {
            let Some(offset) = haystack[from..].find(&needle) else { break };
            let byte = from + offset;
            let first = haystack[..byte].chars().count();
            let chars = needle.chars().count();
            if let (Some(&start_col), Some(&end_col)) = (cols.get(first), cols.get(first + chars - 1)) {
                // The cell right after the match gives the exact end, which
                // keeps CJK hits at full width.
                let end = cols.get(first + chars).copied().unwrap_or(end_col + 1);
                out.push((row, start_col, end.saturating_sub(start_col)));
            }
            from = byte + haystack[byte..].chars().next().map_or(1, char::len_utf8);
        }
    }
    out
}

/// Visible text of the whole screen, used when 复制 is invoked without a
/// selection.
pub fn visible_text(parser: &vt100::Parser) -> String {
    let screen = parser.screen();
    let rows = screen.size().0;
    let mut lines: Vec<String> = (0..rows)
        .map(|row| {
            row_chars(screen, row)
                .iter()
                .map(|(text, _)| text.as_str())
                .collect::<String>()
                .trim_end()
                .to_string()
        })
        .collect();
    while lines.last().is_some_and(|line| line.is_empty()) {
        lines.pop();
    }
    lines.join("\n")
}

/// Shell-style word under the cursor (double-click / long-press selection).
///
/// Delimiters follow upstream: whitespace and shell punctuation split words,
/// while paths, flags and URLs stay together.
pub fn word_bounds(parser: &vt100::Parser, row: u16, col: u16) -> Option<((u16, u16), (u16, u16))> {
    let screen = parser.screen();
    let chars = row_chars(screen, row);
    let index = chars.iter().position(|(_, start)| *start >= col)?;
    if chars[index].1 != col {
        return None;
    }
    let is_word = |text: &str| {
        text.chars()
            .next()
            .is_some_and(|ch| !ch.is_whitespace() && !"\"'`|&;()[]{}<>,".contains(ch))
    };
    if !is_word(&chars[index].0) {
        return None;
    }
    let mut start = index;
    while start > 0 && is_word(&chars[start - 1].0) {
        start -= 1;
    }
    let mut end = index + 1;
    while end < chars.len() && is_word(&chars[end].0) {
        end += 1;
    }
    let start_col = chars[start].1;
    let end_col = chars
        .get(end)
        .map(|(_, next)| next.saturating_sub(1))
        .unwrap_or_else(|| screen.size().1.saturating_sub(1));
    Some(((row, start_col), (row, end_col)))
}

/// Clipboard text → PTY bytes, mirroring upstream `encode_pasted_text`.
pub fn paste_bytes(text: &str, bracketed: bool) -> Vec<u8> {
    let normalized = text.replace("\r\n", "\n");
    let bytes = if bracketed {
        let mut out = Vec::with_capacity(normalized.len() + 12);
        out.extend_from_slice(b"\x1b[200~");
        out.extend_from_slice(normalized.as_bytes());
        out.extend_from_slice(b"\x1b[201~");
        out
    } else {
        normalized.into_bytes()
    };
    bytes
}

fn contains_cjk(text: &str) -> bool {
    text.chars().any(|ch| {
        let cp = ch as u32;
        (0x2E80..=0x9FFF).contains(&cp)      // CJK radicals .. unified ideographs
            || (0xAC00..=0xD7AF).contains(&cp) // Hangul
            || (0xF900..=0xFAFF).contains(&cp) // compatibility ideographs
            || (0x20000..=0x2FA1F).contains(&cp) // supplementary ideographs
            || (0xFF00..=0xFFEF).contains(&cp) // full-width forms
    })
}

/// Slint key text → bytes for the remote PTY.
///
/// Ported from upstream `key_to_pty_bytes` (`src/terminal/impls/input.rs`),
/// plus `Shift+Tab` → CBT, which upstream handles before this call.
pub fn key_bytes(key: &str, ctrl: bool, alt: bool, shift: bool, app_cursor: bool) -> Vec<u8> {
    if shift && !ctrl && !alt && (key == "\u{0019}" || key == "\t") {
        return b"\x1b[Z".to_vec();
    }

    let special: Option<&[u8]> = match key {
        "\u{F700}" => Some(if app_cursor { b"\x1bOA" } else { b"\x1b[A" }),
        "\u{F701}" => Some(if app_cursor { b"\x1bOB" } else { b"\x1b[B" }),
        "\u{F702}" => Some(if app_cursor { b"\x1bOD" } else { b"\x1b[D" }),
        "\u{F703}" => Some(if app_cursor { b"\x1bOC" } else { b"\x1b[C" }),
        "\u{F729}" => Some(if app_cursor { b"\x1bOH" } else { b"\x1b[H" }),
        "\u{F72B}" => Some(if app_cursor { b"\x1bOF" } else { b"\x1b[F" }),
        "\u{F72C}" => Some(b"\x1b[5~"),
        "\u{F72D}" => Some(b"\x1b[6~"),
        "\u{007F}" | "\u{F728}" => Some(b"\x1b[3~"),
        "\u{F704}" => Some(b"\x1bOP"),
        "\u{F705}" => Some(b"\x1bOQ"),
        "\u{F706}" => Some(b"\x1bOR"),
        "\u{F707}" => Some(b"\x1bOS"),
        "\u{F708}" => Some(b"\x1b[15~"),
        "\u{F709}" => Some(b"\x1b[17~"),
        "\u{F70A}" => Some(b"\x1b[18~"),
        "\u{F70B}" => Some(b"\x1b[19~"),
        "\u{F70C}" => Some(b"\x1b[20~"),
        "\u{F70D}" => Some(b"\x1b[21~"),
        "\u{F70E}" => Some(b"\x1b[23~"),
        "\u{F70F}" => Some(b"\x1b[24~"),
        _ => None,
    };
    if let Some(sequence) = special {
        return sequence.to_vec();
    }

    if key == "\u{0008}" {
        return vec![0x7f];
    }
    if key == "\n" && !ctrl && !alt {
        return vec![0x0d];
    }
    if key.is_empty() {
        return Vec::new();
    }

    if let Some(character) = key.chars().next() {
        let codepoint = character as u32;
        if key.chars().count() == 1 && !ctrl && (0x10..=0x18).contains(&codepoint) {
            return Vec::new();
        }
    }

    if ctrl {
        if let Some(character) = key.chars().next() {
            let codepoint = character as u32;
            if key.chars().count() == 1 && (0x01..=0x1f).contains(&codepoint) {
                return vec![codepoint as u8];
            }
        }
        if let Some(character) = key.chars().next() {
            if key.chars().count() == 1 {
                let upper = character.to_ascii_uppercase() as u8;
                let control = match upper {
                    b'A'..=b'Z' => Some(upper - b'A' + 1),
                    b'[' => Some(0x1b),
                    b'\\' => Some(0x1c),
                    b']' => Some(0x1d),
                    b'^' => Some(0x1e),
                    b'_' => Some(0x1f),
                    b'@' => Some(0x00),
                    _ => None,
                };
                if let Some(byte) = control {
                    return vec![byte];
                }
            }
        }
    }

    if key.chars().any(|character| (0xE000..=0xF8FF).contains(&(character as u32))) {
        return Vec::new();
    }
    if alt && !ctrl {
        let mut bytes = vec![0x1b];
        bytes.extend_from_slice(key.as_bytes());
        return bytes;
    }
    key.as_bytes().to_vec()
}
